import React from 'react';
import { useState } from 'react';
import logo from '../../../assets/logo.png';

function Navbar(){
    const [isOpen, setIsOpen] = useState(false);
    return(
      <header className="border-b border-[#E1D5C9] px-[5vw] py-4">
        <div className="flex items-center justify-between">
          <img src="/logo.png" alt="Logo" className="h-[6vh]" />

          <button
            className="md:hidden text-2xl"
            onClick={() => setIsOpen(!isOpen)}
            aria-label="Toggle Navigation"
          >
            ☰
          </button>
        </div>

        <nav
          className={`${
            isOpen ? "flex" : "hidden"
          } flex-col items-center md:flex md:flex-row md:justify-center mt-3 md:mt-0 gap-3 md:gap-8 text-base md:text-lg font-semibold`}
        >
          <a href="#" className="text-[#f48f0f]">Home</a>
          <a href="#">About</a>
          <a href="#">Gallery</a>
          <a href="#">Education</a>
          <button className="bg-[#F48F0F] text-[#292929] py-2 px-5 rounded-full font-semibold text-sm md:text-base">
            Become a member
          </button>
        </nav>
      </header>
    );
}

export default Navbar;
